// @kontent-ai/delivery-sdk v16
import { createDeliveryClient } from "@kontent-ai/delivery-sdk";

// Initializes the Delivery client with `CoreDeliveryClient` type which improves type safety on system fields
// This type is generated by the https://www.npmjs.com/package/@kontent-ai/model-generator
const deliveryClient = createDeliveryClient<CoreDeliveryClient>({
  environmentId: "8d20758c-d74c-4f59-ae04-ee928c0816b7",
});

// Gets an item by codename from Kontent.ai and treats it as a strongly typed model
const homepageItem = (
  await deliveryClient.item<Homepage>("hello_caas_world").toPromise()
).data.item;

// The example above assumes that the item with the codename `hello_caas_world` is of type `Homepage`.
// However, this may not always be the case. To avoid potential runtime errors, it is recommended to
// use generated type guards, such as:
const item = (await deliveryClient.item(`hello_headless_world`).toPromise())
  .data.item;

if (isHomepage(item)) {
  // At this point, the item's type is known, allowing safe and straightforward access to its properties.
  const headline = item.elements.headline.value;
}

// @kontent-ai/delivery-sdk v17
import { createDeliveryClient } from "@kontent-ai/delivery-sdk";

// Initializes the Delivery client with the `TypedClientSchema` and `TypedItem` types which improve type safety
// on codenames, filters, and responses
// These types are generated by the https://www.npmjs.com/package/@kontent-ai/delivery-sdk-model-generator
const deliveryClient = createDeliveryClient<TypedClientSchema, TypedItem>({
  apiMode: "public",
  environmentId: "8d20758c-d74c-4f59-ae04-ee928c0816b7",
});

// Gets items of the `homepage` type from Kontent.ai. The `ofContentTypes` parameter
// narrows the returned items to the strongly typed `HomepageItem` model.
const homepageItems = (
  await deliveryClient.listContentItems({ ofContentTypes: ["homepage"] }).fetchPage()
).payload.items;

// Gets an item by codename from Kontent.ai. The item is typed as a union of all your models (`TypedItem`)
// because its type isn't known before the item is retrieved. To narrow the item to a specific model,
// use generated type guards, such as:
const item = (
  await deliveryClient.fetchContentItem({ codename: "hello_headless_world" }).fetch()
).payload.item;

if (isHomepageItem(item)) {
  // At this point, the item's type is known, allowing safe and straightforward access to its properties.
  const headline = item.elements.headline.value;
}
